style.css:
@-moz-document domain("roblox.com") {
/* Fundo principal e painéis */
    body, 
    .content, 
    .container-main,
    .dark-theme,
    .gandalf-theme {
        background-color: #120e1e !important;
        color: #f1edfa !important;
    }

    /* Barra de navegação superior */
    #header, 
    .navbar-inverse, 
    .rbx-header {
        background-color: #1a132c !important;
        border-bottom: 2px solid #6c5ce7 !important;
    }

    /* Cards de jogos e itens do catálogo */
    .game-card-container, 
    .item-card, 
    .item-card-container, 
    .section-content {
        background-color: #1a132c !important;
        border-radius: 12px !important;
        border: 1px solid #2d2244 !important;
        transition: transform 0.2s ease, border-color 0.2s ease !important;
    }

    /* Efeito de passar o mouse nos cards */
    .game-card-container:hover, 
    .item-card:hover {
        transform: translateY(-4px) !important;
        border-color: #6c5ce7 !important;
    }

    /* Botões principais */
    .btn-common-play-large, 
    .btn-to-play, 
    .btn-primary-md {
        background-color: #6c5ce7 !important;
        border-color: #5849c4 !important;
        border-radius: 8px !important;
    }

    .btn-common-play-large:hover, 
    .btn-primary-md:hover {
        background-color: #5849c4 !important;
    }

    /* Texto de links */
    a, .text-link {
        color: #a29bfe !important;
    }
    
    a:hover {
        color: #6c5ce7 !important;
    }

    /* Remover banners de anúncios poluídos */
    .rbx-upgrade-now, 
    #AdvertisingLeaderboard, 
    .abp {
        display: none !important;
    }
}
